rowdata.pyStepsJavaSource:
lh = new LogHelper("com.pega.pegarules.flowdependencies");
if (((LogHelper)lh).isDebugEnabled()) 
  ((LogHelper)lh).debug("pxCheckFlowDependencies start: " + myStepPage.getXML());

ClipboardPage primePage = tools.getPrimaryPage();
String sClassName = primePage.getClassName();
String errMessage = "The value of the DependencyList parameter is " + tools.getParamValue("DependencyList") + ".\n";
pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pxCheckFlowDependencies", sClassName, errMessage);

try {
	String sActivatorHandle = tools.getDatabase().getHandle(primePage);
	errMessage = "The Flow dependency agent is processing the activator, " + sActivatorHandle + ".\n";
	pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pxCheckFlowDependencies", sClassName, errMessage);
} catch (DatabaseException de) {
  oLog.error(de);
}

String errMessage = "Querying for dependency list \n";
pega_rules_default.LogAgentMessage(tools, "Pega-ProcessEngine", "pxCheckFlowDependencies", tools.getPrimaryPage().getClassName(), errMessage);

ClipboardPage primPage = tools.getPrimaryPage();

ClipboardPage DependencyList = tools.createPage("Code-Pega-List", tools.getParamValue("DependencyList"));

String strDepStatus = tools.getParamValue("DepStatusFromQueue");

String ListofInskeys = tools.getParamValue("ListofInskeys");

DependencyList.putString("pyMaxRecords", "0");

if(strDepStatus.equals(""))
	strDepStatus = primPage.getString(".pyStatusWork");

DependencyList.putString("pyPreparedValues(1)", primPage.getString(".pxObjClass"));
DependencyList.putString("pyPreparedValues(2)", strDepStatus);
DependencyList.putString("pyPreparedValues(3)", ListofInskeys);


// Handle column missing from schema
boolean pyAccessGroupExposed = false;

ClassDefinition indexClass = tools.getDatabase().getClassDef("Index-AssignmentDeps");
if (indexClass != null) {
  try {
    pyAccessGroupExposed = indexClass.isPropertyExposed("pyAccessGroup", tools);
  } catch (DatabaseException ex) {
    oLog.error("Unable to query Index-AssignmentDeps for column pyAccessGroup definition", ex);
    tools.getStepStatus().backoutWorst();
  }
}

String preparedQuery = "select pyCompleteDependentWhen AS \"pyCompleteDependentWhen\", pxInsIndexedKey AS \"pxInsIndexedKey\", pyDependencyClass AS \"pyDependencyClass\", pyDependencyStatus AS \"pyDependencyStatus\", pyActionName AS \"pyActionName\", pyWorkObjectInsKey AS \"pyWorkObjectInsKey\", pyWorkObjectClassName AS \"pyWorkObjectClassName\", pyWaitForAllCases AS \"pyWaitForAllCases\", pyDependencyAncestorClass AS \"pyDependencyAncestorClass\" , pyDependencyScope AS \"pyDependencyScope\"";

if (pyAccessGroupExposed) {
  preparedQuery += " , pyAccessGroup as \"pyAccessGroup\" ";
}

/* BUG-338584 HFix-39248 start */

/*
If the strDepStatus is any of 'Resolved' statuses, then it can satisfy any of below two types of dependencies.
a) Wait shape's - To be Resolved dependency - where 'Resolved-%' is present in pyDependencyStatus db column
b) Wait shape's - To reach status configured to any of 'Resolved' statuses - where 'Resolved-XYZ' is present in pyDependencyStatus db column
So, strDepStatus must match for a) or b) i.e, to put in sql query - pyDependencyStatus IN ('Resolved-XYZ', 'Resolved-%')

If the strDepStatus is not any of 'Resolved' statuses, then it can satisfy only below type of dependency.
a) Wait shape's - To reach status configured to reach status (exact match)
So, strDepStatus must match a) i.e, to put in sql query - pyDependencyStatus = 'XYZ'
*/

if(strDepStatus != null && strDepStatus.startsWith("Resolved-")) {
  preparedQuery += " from {Class:Index-AssignmentDeps}" +
                   " where pyDependencyClass = {" + tools.getParamValue("DependencyList") + ".pyPreparedValues(1)} " +
                   " AND (pyDependencyStatus IN ({" + tools.getParamValue("DependencyList") + ".pyPreparedValues(2)}, 'Resolved-%')) " +
                   " AND pyWorkObjectInsKey IN ("+tools.getParamValue("ListofInskeys")+")";
} else {
  preparedQuery += " from {Class:Index-AssignmentDeps}" +
                   " where pyDependencyClass = {" + tools.getParamValue("DependencyList") + ".pyPreparedValues(1)} " +
                   " AND pyDependencyStatus = {" + tools.getParamValue("DependencyList") + ".pyPreparedValues(2)} " +
                   " AND pyWorkObjectInsKey IN ("+tools.getParamValue("ListofInskeys")+")";
}
/* BUG-338584 HFix-39248 end */

try{
  if (((LogHelper)lh).isDebugEnabled()) 
    ((LogHelper)lh).debug("Running query to get DependencyList: " +preparedQuery);

  tools.getDatabase().executeRDB(preparedQuery, DependencyList);

} catch(DatabaseException dbe){
  oLog.error("Unable to query to get dependent assignments for: " + primPage.getString("pzInsKey"), dbe);
}

ClipboardPage primPage = tools.getPrimaryPage();
String strDepStatus = tools.getParamValue("DepStatusFromQueue");
if(strDepStatus.equals(""))
	strDepStatus = primPage.getString(".pyStatusWork");

ClipboardPage DependencyList = tools.findPage(tools.getParamValue("DependencyList"));
// start get deferred saved work objects
PegaDatabase db = (PegaDatabase) tools.getDatabase();
java.util.Iterator deferredOps = db.getDeferredOps().iterator();
java.util.Map deferredWOMap = new java.util.HashMap();
while (deferredOps.hasNext()) {
	DeferredOperation op = (DeferredOperation) deferredOps.next(); 
	ClipboardPage instancePage = null;
	if (op instanceof DeferredOperation.SaveInstance){  
  		DeferredOperation.SaveInstance tempOpVal = (DeferredOperation.SaveInstance) op;
  		instancePage = tempOpVal.getInstance();
	}else{
    /* 
    we dont need about the other possibilities, which are:
    DeferredOperation.DeleteInstance
    DeferredOperation.DeleteChangesForDeclarative
    DeferredOperation.DeleteIndex 
    DeferredOperation.DeleteIndexesForInstance 
    DeferredOperation.DeletePurposeForInstance 
    DeferredOperation.SaveChangeForDeclarative 
    DeferredOperation.SaveIndex 
    */  
    continue;
	}	
	if(instancePage.getString("pxObjClass").equals("Assign-WorkBasket") && instancePage.getString("pyDependencyClass").equals(primPage.getString(".pxObjClass")) 
		&& pega_processengine_workutilities.pzEvaluateDependencyRelation(instancePage.getString("pyDependencyStatus"),strDepStatus)){

          	// if its already present it gets overrridden by latest copy
          	deferredWOMap.put(instancePage.getString("pzInsKey"), instancePage);	

     		ClipboardProperty resultPage = DependencyList.getProperty("pxResults");
			ClipboardPage newPage = tools.createPage("Index-AssignmentDeps", "");
			newPage.put("pyDependencyStatus" , instancePage.getProperty("pyDependencyStatus") );
			newPage.put("pyActionName" , instancePage.getProperty("pyActionName") );
			newPage.put("pyWorkObjectClassName" , instancePage.getProperty("pyWorkObjectClassName") );
			newPage.put("pyWorkObjectInsKey" , instancePage.getProperty("pxRefObjectKey") );
			newPage.put("pyWaitForAllCases" , instancePage.getProperty("pyWaitForAllCases") );
			newPage.put("pyCompleteDependentWhen" , instancePage.getProperty("pyCompleteDependentWhen") );
			newPage.put("pxCreateDateTime" , instancePage.getProperty("pxCreateDateTime") );
			newPage.put("pxCreateOpName" , instancePage.getProperty("pxCreateOpName") );
			newPage.put("pxCreateOperator" , instancePage.getProperty("pxCreateOperator") );
			newPage.put("pxCreateSystemID" , instancePage.getProperty("pxCreateSystemID") );
			newPage.put("pyDependencyAncestorClass" , instancePage.getProperty("pyDependencyAncestorClass") );
	        newPage.put("pyAccessGroup" , instancePage.getProperty("pyAccessGroup") );
			newPage.put("pxInsIndexedKey" , instancePage.getProperty("pzIndexOwnerKey") );
			resultPage.add(newPage);


	}
}
